def parse_nested_parens(paren_string: str) -> List[int]:
    result = []

    # Split input string by spaces into groups
    groups = paren_string.split()

    for group in groups:
        current_level = 0
        max_level = 0

        for char in group:
            if char == '(':
                current_level += 1
                if current_level > max_level:
                    max_level = current_level
            elif char == ')':
                current_level -= 1

        result.append(max_level)

    return result
